\foreach \x [evaluate=\x as \y using f(\x)] in {5.3,5.6,...,8.4}{
	\edef\temp{
		\noexpand
		\node[circle, draw=none, fill=deepskyblue, inner sep=1.5pt] at (axis cs: \x, \y+rand*\spread) {};
	}\temp
}

\draw[->, fadedpink, thick, shorten <      = 1.5mm, shorten >= 1.5mm] (axis cs:5,0) -- (axis cs:5,1) node[circle, inner sep=2pt, draw=none, fill=red] {};

\end{axis}

\end{tikzpicture}
\end{document}

